<!doctype html>
<html lang="<?= e(LocaleService::language()) ?>"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><?php require ROOT.'/app/Core/views/locale-scripts.php'; ?><title><?= e(t('LifeOS desktop panel')) ?></title><link rel="stylesheet" href="/assets/desktop-panel.css"></head>
